class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def all_subs(x: str):
            L = len(x)
            subs = {""}
            for i in range(L):
                for j in range(i + 1, L + 1):
                    subs.add(x[i:j])
            return sorted(subs, key=len, reverse=True)

        subs_s = all_subs(s)
        subs_t = all_subs(t)
        max_len_t = len(subs_t[0])

        best = 0
        for a in subs_s:
            la = len(a)
            if la + max_len_t <= best:
                break
            for b in subs_t:
                total = la + len(b)
                if total <= best:
                    break
                c = a + b
                if c == c[::-1]:
                    best = total
        return best
